INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('manufacturing', 'mfg_ods_po_dwd', 'ods_production_order', 'dwd_production_wide', 'ODS', 'DWD', 'ODS → DWD → DWS', '灌入后 / T+1', 'python', 'portfolio/industries/manufacturing/database/seed_manufacturing_data.py', 'load_dwd_production_wide', '工单贴源 JOIN dim_production_line / dim_product，冗余产线名/产品名；按计划与实际产量派生材料/人工/制造费用代理成本。', 'INSERT INTO dwd_production_wide SELECT o.*, l.line_name, p.product_name, ... FROM ods_production_order o LEFT JOIN dim_*', '工单级明细');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('manufacturing', 'mfg_ods_qi_dwd', 'ods_quality_inspection', 'dwd_quality_wide', 'ODS', 'DWD', 'ODS → DWD → DWS', '灌入后 / T+1', 'python', 'portfolio/industries/manufacturing/database/seed_manufacturing_data.py', 'load_dwd_quality_wide', '质检单 JOIN 产线/产品维；良品率 = pass_qty / NULLIF(total_qty,0) * 100。', 'yield_rate = pass_qty / NULLIF(total_qty,0) * 100', '质检单级');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('manufacturing', 'mfg_ods_inv_dwd', 'ods_inventory_material', 'dwd_supply_wide', 'ODS', 'DWD', 'ODS → DWD → DWS', '灌入后 / T+1', 'python', 'portfolio/industries/manufacturing/database/seed_manufacturing_data.py', 'load_dwd_supply_wide', '库存快照 JOIN dim_material / dim_supplier，形成供应事实宽表（日×物料×供应商粒度）。', 'INSERT INTO dwd_supply_wide SELECT i.*, m.material_name, s.supplier_name ...', '日×物料×供应商');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('manufacturing', 'mfg_ods_labor_dwd', 'ods_labor', 'dwd_labor_wide', 'ODS', 'DWD', 'ODS → DWD → DWS', '灌入后', 'python', 'portfolio/industries/manufacturing/database/seed_enhance.py', 'load_dwd_labor_wide', '工时明细 JOIN 产线与工单，冗余工厂/产品维度，供人效与成本下钻。', 'INSERT INTO dwd_labor_wide SELECT l.*, line.factory_code, o.product_code ...', '工时记录级');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('manufacturing', 'mfg_ods_eq_dwd', 'ods_equipment', 'dwd_equipment_run', 'ODS', 'DWD', '样例灌入', '按需', 'python', 'portfolio/industries/manufacturing/database/seed_enhance.py', 'expand_equipment_run', '由日 OEE/设备台账展开为班次运行事实（计划/运行/停机分钟）。', 'INSERT INTO dwd_equipment_run SELECT equipment_code, shift, planned_min, run_min, downtime_min ...', '设备×日×班次');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('manufacturing', 'mfg_dwd_prod_dws', 'dwd_production_wide', 'dws_production_daily', 'DWD', 'DWS', 'ODS → DWD → DWS', '灌入后 / T+1', 'python', 'portfolio/industries/manufacturing/database/seed_manufacturing_data.py', 'load_dws_production_daily', '按日×厂×线汇总产量/计划；产能利用率与准时交付率按产量加权，禁止对百分比做简单 AVG。', 'SUM(output_qty); capacity_util = SUM(util*qty)/SUM(qty)', '日×工厂×产线');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('manufacturing', 'mfg_dwd_qi_dws', 'dwd_quality_wide', 'dws_quality_daily', 'DWD', 'DWS', 'ODS → DWD → DWS', '灌入后 / T+1', 'python', 'portfolio/industries/manufacturing/database/seed_manufacturing_data.py', 'load_dws_quality_daily', '日×线×产品汇总检验量/合格/不良/报废；良品率与 FPY 按检验量加权。', 'yield_rate_pct = SUM(pass)/SUM(total)*100', '日×产线×产品');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('manufacturing', 'mfg_dwd_sup_dws', 'dwd_supply_wide', 'dws_supply_daily', 'DWD', 'DWS', 'ODS → DWD → DWS', '灌入后 / T+1', 'python', 'portfolio/industries/manufacturing/database/seed_manufacturing_data.py', 'load_dws_supply_daily', '供应日汇总：采购额、库存周转天数、供应商 OTD；金额类作权重。', 'GROUP BY snapshot_date, material_code, supplier_code', '日×物料×供应商');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('manufacturing', 'mfg_ods_labor_dws', 'ods_labor', 'dws_labor_monthly', 'ODS', 'DWS', 'ODS → DWD → DWS', '灌入后 / T+1', 'python', 'portfolio/industries/manufacturing/database/seed_manufacturing_data.py', 'load_dws_labor_monthly', '按月×工厂×产线 SUM(plan_hours/actual_hours/labor_cost)；工时达成率 = actual/plan*100；同步见 06_migrate_dws_ads.sql。', 'INSERT INTO dws_labor_monthly SELECT DATE_FORMAT(work_date,''%Y-%m''), factory_code, line_code, SUM(...)', '月×工厂×产线');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('manufacturing', 'mfg_ods_labor_dws_sql', 'ods_labor', 'dws_labor_monthly', 'ODS', 'DWS', 'ODS → DWD → DWS', '迁移补数', 'sql', 'portfolio/industries/manufacturing/database/06_migrate_dws_ads.sql', 'DELETE/INSERT dws_labor_monthly', 'SQL 迁移脚本：从 ods_labor 重算月人工效率快照，与 Python seed 口径对齐。', 'INSERT INTO dws_labor_monthly SELECT DATE_FORMAT(work_date,''%Y-%m''), ... FROM ods_labor GROUP BY 1,2,3', '月×工厂×产线');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('manufacturing', 'mfg_ods_inv_mat_dws', 'ods_inventory_material', 'dws_material_daily', 'ODS', 'DWS', 'ODS → DWD → DWS', '灌入后 / T+1', 'python', 'portfolio/industries/manufacturing/database/seed_manufacturing_data.py', 'load_dws_material_daily', '周转天数 = on_hand_qty / NULLIF(daily_usage,0)；库存金额 = qty × standard_price。', 'turnover_days = on_hand_qty / NULLIF(daily_usage,0)', '日×物料');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('manufacturing', 'mfg_ods_qi_defect_dws', 'ods_quality_inspection', 'dws_defect_daily', 'ODS', 'DWS', 'ODS → DWD → DWS', '灌入后 / T+1', 'python', 'portfolio/industries/manufacturing/database/seed_manufacturing_data.py', 'load_dws_defect_daily', '按日×缺陷类型×产线汇总不良/报废；不良率 = defect/total*100。', 'GROUP BY snapshot_date, defect_type, line_code', '日×缺陷类型×产线');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('manufacturing', 'mfg_ods_eq_dws', 'ods_equipment', 'dws_equipment_daily', 'ODS', 'DWS', 'ODS → DWD → DWS', '灌入后 / T+1', 'python', 'portfolio/industries/manufacturing/database/seed_manufacturing_data.py', 'load_dws_equipment_daily', '设备日 OEE = 可用率×性能率×质量率；汇总停机小时与故障次数。', 'oee_pct = availability * performance * quality / 10000', '日×设备');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('manufacturing', 'mfg_dws_prod_ads', 'dws_production_daily', 'v_production_overview', 'DWS', 'ADS', 'ADS 视图', '实时', 'view', 'portfolio/industries/manufacturing/database/05_ads.sql', 'CREATE VIEW v_production_overview', '排除 ALL 汇总行后按日加权产能利用率与准时交付率，供生产总览看板。', 'SELECT snapshot_date, SUM(output_qty), SUM(util*qty)/SUM(qty) FROM dws_production_daily WHERE line_code<>''ALL''', '日汇总切片');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('manufacturing', 'mfg_dws_labor_ads', 'dws_labor_monthly', 'v_labor_efficiency', 'DWS', 'ADS', 'ADS 视图', '实时', 'view', 'portfolio/industries/manufacturing/database/05_ads.sql', 'CREATE VIEW v_labor_efficiency', 'ADS 只读投影月人工效率快照（计划/实际工时、达成率、人工成本），禁止回读 ODS。', 'CREATE OR REPLACE VIEW v_labor_efficiency AS SELECT * FROM dws_labor_monthly 列投影', '月×工厂×产线');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('manufacturing', 'mfg_dws_mat_ads', 'dws_material_daily', 'v_material_turnover', 'DWS', 'ADS', 'ADS 视图', '实时', 'view', 'portfolio/industries/manufacturing/database/05_ads.sql', 'CREATE VIEW v_material_turnover', '物料周转看板直接消费 DWS 日物料周转指标。', 'SELECT snapshot_date, material_code, turnover_days, on_hand_amount FROM dws_material_daily', '日×物料');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('manufacturing', 'mfg_dws_def_ads', 'dws_defect_daily', 'v_defect_analysis', 'DWS', 'ADS', 'ADS 视图', '实时', 'view', 'portfolio/industries/manufacturing/database/05_ads.sql', 'CREATE VIEW v_defect_analysis', '不良分析看板读 DWS 缺陷日汇总，做柏拉图与结构分析。', 'SELECT * FROM dws_defect_daily', '日×缺陷类型');
