INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('manufacturing', 'mfg_dws_eq_ads', 'dws_equipment_daily', 'v_equipment_oee', 'DWS', 'ADS', 'ADS 视图', '实时', 'view', 'portfolio/industries/manufacturing/database/05_ads.sql', 'CREATE VIEW v_equipment_oee', '设备 OEE 看板直读 DWS 日指标。', 'SELECT snapshot_date, equipment_code, oee_pct, downtime_hours FROM dws_equipment_daily', '日×设备');
