INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('internet', 'inet_ods_op_dwd', 'ods_device_operation_log', 'dwd_device_operation_wide', 'ODS', 'DWD', 'ODS → DWD → DWS', '灌入后', 'python', 'portfolio/industries/internet/database/seed_internet_data.py', 'build_dwd_device_operation_wide', '开机/点播/直播操作日志 JOIN 设备与用户维，形成行为宽表。', 'INSERT INTO dwd_device_operation_wide SELECT log.*, device.*, user.* ...', '一次设备行为');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('internet', 'inet_ods_user_dwd', 'ods_user_profile', 'dwd_user_wide', 'ODS', 'DWD', 'ODS → DWD → DWS', '灌入后', 'python', 'portfolio/industries/internet/database/seed_internet_data.py', 'build_dwd_user_wide', '用户档案宽表；再 UPDATE last_active / is_paid（来自行为与订购）。', 'INSERT INTO dwd_user_wide ...; UPDATE ... JOIN dwd_device_operation_wide', '用户');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('internet', 'inet_dwd_op_session', 'dwd_device_operation_wide', 'dwd_session_wide', 'DWD', 'DWD', 'ODS → DWD → DWS', '灌入后', 'python', 'portfolio/industries/internet/database/seed_internet_data.py', 'build_dwd_session_wide', '按 session_id 汇总行为次数与时长。', 'INSERT INTO dwd_session_wide SELECT session_id, user_id, COUNT(*), SUM(duration) ... GROUP BY session_id', '会话');
INSERT INTO etl_transform_edge (industry, edge_id, from_table, to_table, layer_from, layer_to, job_name, schedule, engine, code_path, entry_point, computation, sql_excerpt, grain) VALUES ('internet', 'inet_ods_sub_dws', 'ods_subscription_order', 'dws_payment_daily', 'ODS', 'DWS', 'ODS → DWD → DWS', '灌入后', 'python', 'portfolio/industries/internet/database/seed_internet_data.py', 'build_dws_payment_daily', '订购按支付日×渠道×产品线汇总付费用户/金额/ARPU。', 'GROUP BY pay_date, channel_code, product_line; arpu = pay_amount/pay_users', '日×渠道×产品线');
